46:         if (res.statusCode >= 200 && res.statusCode < 400) {
47:           resolve({ status: res.statusCode, body: data });
48:         } else {
49:           reject(new Error(`HTTP ${res.statusCode}: ${data.slice(0, 100)}`));
50:         }
51:       });
52:     });
53: 
54:     req.on('error', reject);
55:     req.on('timeout', () => {
56:       req.destroy();
57:       reject(new Error(`Request timed out after ${reqOpts.timeout}ms`));
58:     });
